using System.Security.Claims;using MaintenancePRO.Api.Contracts;using MaintenancePRO.Api.Data;using MaintenancePRO.Api.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/admin"),Authorize(Policy="AdminOnly")]
public sealed class AdminController(UserManager<ApplicationUser> users,AppDbContext db):ControllerBase{
[HttpGet("users")] public async Task<IActionResult> UsersList()=>Ok(await users.Users.AsNoTracking().Select(u=>new{id=u.Id,email=u.Email,displayName=u.DisplayName,status=u.Status,createdUtc=u.CreatedUtc}).ToListAsync());
[HttpPatch("users/{id}/status")] public async Task<IActionResult> SetStatus(string id,SetAccountStatusRequest r){var u=await users.FindByIdAsync(id);if(u==null)return NotFound();if(u.Id==User.FindFirstValue(ClaimTypes.NameIdentifier))return BadRequest(new{message="Ne modifie pas ton propre statut depuis cet endpoint."});u.Status=r.Status;var result=await users.UpdateAsync(u);if(!result.Succeeded)return BadRequest(new{errors=result.Errors.Select(e=>e.Code)});db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action="AccountStatusChanged",EntityType="User",EntityId=id});await db.SaveChangesAsync();return Ok(new{id=u.Id,email=u.Email,status=u.Status});}
[HttpPut("users/{id}/role")] public async Task<IActionResult> SetRole(string id,SetRoleRequest r){var valid=new[]{AppRoles.Admin,AppRoles.Supervisor,AppRoles.Technician,AppRoles.User};if(!valid.Contains(r.Role))return BadRequest(new{message="Rôle invalide."});var u=await users.FindByIdAsync(id);if(u==null)return NotFound();if(u.Id==User.FindFirstValue(ClaimTypes.NameIdentifier)&&r.Role!=AppRoles.Admin)return BadRequest(new{message="Évite de modifier ton propre rôle."});var current=await users.GetRolesAsync(u);var remove=await users.RemoveFromRolesAsync(u,current);if(!remove.Succeeded)return BadRequest(new{errors=remove.Errors.Select(e=>e.Code)});var add=await users.AddToRoleAsync(u,r.Role);if(!add.Succeeded)return BadRequest(new{errors=add.Errors.Select(e=>e.Code)});db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action="UserRoleChanged",EntityType="User",EntityId=id});await db.SaveChangesAsync();return Ok(new{id=u.Id,role=r.Role});}
[HttpGet("audit")] public async Task<IActionResult> Audit([FromQuery]int take=100)=>Ok(await db.AuditEvents.AsNoTracking().OrderByDescending(x=>x.CreatedUtc).Take(Math.Clamp(take,1,500)).ToListAsync());
[HttpGet("dashboard")] public async Task<IActionResult> Dashboard()=>Ok(new{equipmentCount=await db.Equipments.CountAsync(),openInterventions=await db.Interventions.CountAsync(x=>x.Status!=InterventionStatus.Completed&&x.Status!=InterventionStatus.Closed&&x.Status!=InterventionStatus.Cancelled&&x.Status!=InterventionStatus.Rejected),completedInterventions=await db.Interventions.CountAsync(x=>x.Status==InterventionStatus.Completed||x.Status==InterventionStatus.Closed),pendingAccounts=await users.Users.CountAsync(x=>x.Status==AccountStatus.Pending)});}
